// DSHA_OPENAI_SSE_FRAMING_V1: 无 data 字段的控制块不产生 JSON 事件；数据帧仍严格解析。
class SSEDecoder {
    constructor() {
        this.event = null;
        this.data = [];
        this.chunks = [];
    }
    decode(line) {
        if (line.endsWith('\r')) {
            line = line.slice(0, -1);
        }
        if (!line) {
            // SSE 规范：没有 data 字段时仅复位事件类型；不能把空 JSON 送给协议层。
            // data:（显式空值）仍会产生事件，由 JSON.parse 报错，绝不吞掉坏数据。
            const sse = this.data.length === 0 ? null : {
                event: this.event || null,
                data: this.data.join('\n'),
                raw: this.chunks,
            };
            this.event = null;
            this.data = [];
            this.chunks = [];
            return sse;
        }
        // 心跳注释不属于数据，避免长时间等待时累计无用诊断副本。
        if (line.startsWith(':')) {
            return null;
        }
        const [fieldname, , initialValue] = partition(line, ':');
        let value = initialValue;
        if (value.startsWith(' ')) {
            value = value.slice(1);
        }
        if (fieldname === 'event') {
            this.event = value;
        }
        else if (fieldname === 'data') {
            this.data.push(value);
        }
        else {
            return null;
        }
        this.chunks.push(line);
        return null;
    }
    flush() {
        // 保留 SDK 对缺少末尾空行的完整 JSON 的兼容；不完整 JSON 仍由协议层拒绝。
        return this.decode('');
    }
}

